const views={"echo":View3};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"echo";}
export function ArtemisNotFoundPages({className,variant="echo"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesEcho() {
    const reduce = useReducedMotion();
    const [shown, setShown] = useState(false);
    const [active, setActive] = useState(false);
    const [captionShown, setCaptionShown] = useState(false);
    useEffect(() => {
        if (reduce) {
            setShown(true);
            setCaptionShown(true);
            return;
        }
        const timer = setTimeout(() => setShown(true), 70);
        const captionTimer = setTimeout(() => setCaptionShown(true), 240);
        return () => { clearTimeout(timer); clearTimeout(captionTimer); };
    }, [reduce]);
    const layer = (index: number) => ({
        initial: { opacity: 0, scale: 0.96, y: 0 },
        animate: shown ? { opacity: [0.16, 0.28, 1, 0.28, 0.16][index], scale: 1, y: (active && !reduce ? [-58, -30, 0, 30, 58] : [-28, -14, 0, 14, 28])[index] } : undefined,
        transition: reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: index * 0.045 },
    });
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <section className="art:flex art:min-h-[680px] art:w-full art:flex-col art:overflow-hidden art:bg-muted art:text-foreground art:[container-type:inline-size]">
        <header className="art:flex art:min-h-20 art:items-center art:justify-between art:px-5 art:@min-[640px]/artemis:px-8">
          <a href="/" className="art:font-medium art:text-sm art:focus-visible:outline-2 art:focus-visible:outline-ring">
            {"Home"}
          </a>
          <span className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.18em]">
            {"No response"}
          </span>
        </header>
        <div className="art:flex art:flex-1 art:flex-col art:items-center art:justify-center art:px-5 art:py-10 art:text-center">
          <motion.button onMouseEnter={() => setActive(true)} onMouseLeave={() => setActive(false)} onFocus={() => setActive(true)} onBlur={() => setActive(false)} {...press} type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:h-[35cqw] art:max-h-[360px] art:min-h-48 art:w-full art:cursor-default art:rounded-full" aria-label="404. Hover to fan out the echoes." tabIndex={0}>
            <motion.span {...layer(0)} aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.1em]">
              {"404"}
            </motion.span>
            <motion.span {...layer(1)} aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.1em]">
              {"404"}
            </motion.span>
            <motion.span {...layer(2)} aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.1em]">
              {"404"}
            </motion.span>
            <motion.span {...layer(3)} aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.1em]">
              {"404"}
            </motion.span>
            <motion.span {...layer(4)} aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-none art:tracking-[-0.1em]">
              {"404"}
            </motion.span>
          </motion.button>
          <motion.h1 initial={{ opacity: 0 }} animate={captionShown ? { opacity: 1 } : undefined} transition={reduce ? { duration: 0 } : { duration: 0.2, ease: "easeOut" }} className="art:tracking-[-0.03em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium">
            {"No page answered."}
          </motion.h1>
          <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:h-9 art:rounded-full" href="/" tabIndex={0}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-left art:size-4" aria-hidden="true">
              <path d="m12 19-7-7 7-7"/>
              <path d="M19 12H5"/>
            </svg>
            {"Return home"}
          </motion.a>
        </div>
      </section>
    </>);
}
